CREATE OR REPLACE FUNCTION public.lead_company_stages(_company uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.uid() IS NULL OR NOT coalesce(public.user_crm_company(_company),false) THEN RAISE EXCEPTION 'Company access denied'; END IF;
RETURN coalesce((SELECT jsonb_agg(to_jsonb(s)||jsonb_build_object('board_label',coalesce(c.label,s.board_label,s.name),'color',coalesce(c.color,s.color),'position',coalesce(c.position,s.position),'is_default',coalesce(c.is_default,false) OR (s.board_initial AND NOT EXISTS(SELECT 1 FROM public.company_lead_status d JOIN public.crm_stages ds ON ds.id=d.stage_id WHERE d.company_id=_company AND ds.pipeline_id=s.pipeline_id AND d.is_default AND NOT d.hidden))) ORDER BY s.pipeline_id,coalesce(c.position,s.position),s.id) FROM public.crm_stages s LEFT JOIN public.company_lead_status c ON c.stage_id=s.id AND c.company_id=_company WHERE s.kind='lead' AND (s.company_id IS NULL OR s.company_id=_company) AND NOT coalesce(c.hidden,false)),'[]'::jsonb);
END $$;